def solve_pa(a):
    target = 12 * a + 1
    if target <= 1:
        return None

    # Check if target is a perfect power
    for p in range(2, int(target**(1/a)) + 2):
        if p**a == target:
            # Check if p is prime
            is_prime = True
            if p < 2:
                is_prime = False
            else:
                for i in range(2, int(p**0.5) + 1):
                    if p % i == 0:
                        is_prime = False
                        break
            if is_prime:
                return p
    return None

solutions = {}
for a in range(1, 7):
    p = solve_pa(a)
    if p is not None:
        n = p**a
        solutions[a] = (p, n)

print(solutions)
